mapper.select:
SELECT * FROM (
  SELECT  FROM  
  UNION ALL
  SELECT kind,-id,user_id,'—','REJECTED',0,0,0,0,0,0,created_at
  FROM rejected_imports WHERE kind=#{kind}
) b ORDER BY created_at DESC,id DESC LIMIT #{size} OFFSET #{offset}

choose.when:
SELECT kind,-id AS id,user_id,'—' AS format,'REJECTED' AS status,0 AS total_rows,0 AS valid_rows,
  0 AS invalid_rows,0 AS duplicate_rows,0 AS unsupported_rows,0 AS inserted_rows,created_at
FROM rejected_imports WHERE kind=#{kind} AND id=-#{id}
